<?php
defined('WB_PATH') or die('No direct access');
function wbce_safebanner_settings(): array {$raw=Settings::get('cookie_banner_safebanner','');$data=json_decode((string)$raw,true);return array_merge(array('position'=>'bottom','theme'=>'light','color'=>'#1769aa','company'=>'','lang'=>'de','google_consent'=>'advanced','layout'=>'banner','project_key'=>'','logo'=>'','button_style'=>'default','title'=>'','description'=>'','accept'=>'','reject'=>'','customize'=>'','save'=>'','radius'=>'','max_width'=>'','offset'=>'','expiry_days'=>'','pro_enabled'=>'0','show_revoke'=>'1','revoke_position'=>'bottom-left','revoke_title'=>'Cookie-Einstellungen ändern','revoke_background'=>'#ffffff','revoke_text'=>'#1769aa'),is_array($data)?$data:array());}
function wbce_safebanner_value(string $name): string {$s=wbce_safebanner_settings();return htmlspecialchars((string)($s[$name]??''),ENT_QUOTES,'UTF-8');}
function wbce_safebanner_select(string $name,array $options): string {$current=htmlspecialchars_decode(wbce_safebanner_value($name));$html='<select name="cookie_safebanner_'.$name.'">';foreach($options as $value=>$label)$html.='<option value="'.htmlspecialchars($value,ENT_QUOTES,'UTF-8').'"'.($current===$value?' selected':'').'>'.htmlspecialchars($label,ENT_QUOTES,'UTF-8').'</option>';return $html.'</select>';}
if(function_exists('wbce_add_filter'))wbce_add_filter('cookie_banner.providers',static function($items){
    $items['safebanner']=array('name'=>'SafeBanner','description'=>'Lokal gehostet mit Consent Mode v2 und optionaler Pro-Lizenz.','render'=>static function($categories,$central){
        $s=wbce_safebanner_settings();$pro=!empty($s['pro_enabled']);$attributes=array('data-position'=>$s['position'],'data-theme'=>($pro?$s['theme']:($s['theme']==='dark'?'dark':'light')),'data-color'=>$s['color'],'data-company'=>$s['company'],'data-privacy'=>$central['privacy_url']??'','data-lang'=>$s['lang'],'data-google-consent'=>$s['google_consent'],'data-layout'=>($pro?$s['layout']:''),'data-project-key'=>($pro?$s['project_key']:''),'data-logo'=>($pro?$s['logo']:''),'data-button-style'=>($pro?$s['button_style']:''),'data-banner-title'=>($pro?$s['title']:''),'data-banner-description'=>($pro?$s['description']:''),'data-accept-label'=>($pro?$s['accept']:''),'data-reject-label'=>($pro?$s['reject']:''),'data-customize-label'=>($pro?$s['customize']:''),'data-save-label'=>($pro?$s['save']:''),'data-radius'=>($pro?$s['radius']:''),'data-max-width'=>($pro?$s['max_width']:''),'data-offset'=>($pro?$s['offset']:''),'data-consent-expiry-days'=>($pro?$s['expiry_days']:''));$attrs='';foreach($attributes as $name=>$value)if($value!=='')$attrs.=' '.$name.'="'.htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8').'"';$categoryJson=json_encode($categories,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);$src=WB_URL.'/modules/cookie_banner_safebanner/assets/safebanner.js';$adapter=WB_URL.'/modules/cookie_banner_safebanner/assets/safebanner-categories.js';return '<link rel="stylesheet" href="'.WB_URL.'/modules/cookie_banner_safebanner/assets/safebanner-categories.css"><script src="'.$src.'"'.$attrs.' defer></script><script src="'.$adapter.'" defer></script><script>(function(){function start(){if(window.WbceSafeBannerCategories){window.WbceSafeBannerCategories.configure('.$categoryJson.','.(empty($s['show_revoke'])?'false':'true').','.json_encode(array('position'=>$s['revoke_position'],'title'=>$s['revoke_title'],'background'=>$s['revoke_background'],'text'=>$s['revoke_text']),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).');window.WbceSafeBannerCategories.start();}}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",start);else start();})();</script>';});return $items;
});
if(function_exists('wbce_add_filter'))wbce_add_filter('cookie_banner.settings.sections',static function($sections){
$v='wbce_safebanner_value';$sections[]='<section class="cookie-provider-main-frame cookie-provider-settings" data-provider="safebanner"><div class="cookie-provider-main-frame__header"><i class="fa fa-shield" aria-hidden="true"></i><h3>SafeBanner</h3></div><p>Felder mit „Pro“ benötigen eine gültige SafeBanner-Projektlizenz.</p><div class="cookie-checkboxes"><label><input type="checkbox" name="cookie_safebanner_show_revoke" value="1"'.(wbce_safebanner_value('show_revoke')==='1'?' checked':'').'> Widerruf anzeigen</label><label><input type="checkbox" name="cookie_safebanner_pro_enabled" value="1"'.(wbce_safebanner_value('pro_enabled')==='1'?' checked':'').'> Pro verwenden (gültige Lizenz nötig)</label></div><div class="cookie-banner-grid"><label>Consent-Position'.wbce_safebanner_select('position',array('bottom'=>'Unten','top'=>'Oben','bottom-left'=>'Unten links','bottom-right'=>'Unten rechts')).'</label><label>Widerruf Position'.wbce_safebanner_select('revoke_position',array('bottom-left'=>'Unten links','bottom-right'=>'Unten rechts','top-left'=>'Oben links','top-right'=>'Oben rechts')).'</label><label>Widerruf Titel<input name="cookie_safebanner_revoke_title" value="'.$v('revoke_title').'"></label><label>Widerruf Hintergrund<input type="color" name="cookie_safebanner_revoke_background" value="'.$v('revoke_background').'"></label><label>Widerruf Text<input type="color" name="cookie_safebanner_revoke_text" value="'.$v('revoke_text').'"></label><label>Darstellung'.wbce_safebanner_select('theme',array('light'=>'Hell','dark'=>'Dunkel','auto'=>'Automatisch (Pro)')).'</label><label>Primärfarbe<input type="color" name="cookie_safebanner_color" value="'.$v('color').'"></label><label>Sprache'.wbce_safebanner_select('lang',array('de'=>'Deutsch','en'=>'Englisch','fr'=>'Französisch')).'</label><label>Google Consent Mode'.wbce_safebanner_select('google_consent',array('advanced'=>'Erweitert','basic'=>'Einfach','off'=>'Aus')).'</label><label>Unternehmen<input name="cookie_safebanner_company" value="'.$v('company').'"></label><div class="cookie-banner-grid" data-pro-field><label>Layout (Pro)'.wbce_safebanner_select('layout',array('banner'=>'Banner','bar'=>'Leiste','card'=>'Karte')).'</label><label>Schaltflächen (Pro)'.wbce_safebanner_select('button_style',array('default'=>'Standard','pill'=>'Rund','square'=>'Eckig')).'</label><label>Projektlizenz (Pro)<input name="cookie_safebanner_project_key" value="'.$v('project_key').'"></label><label>Logo-URL (Pro)<input type="url" name="cookie_safebanner_logo" value="'.$v('logo').'"></label><label>Radius px (Pro)<input type="number" min="0" name="cookie_safebanner_radius" value="'.$v('radius').'"></label><label>Maximale Breite px (Pro)<input type="number" min="200" name="cookie_safebanner_max_width" value="'.$v('max_width').'"></label><label>Abstand px (Pro)<input type="number" min="0" name="cookie_safebanner_offset" value="'.$v('offset').'"></label><label>Einwilligung erneuern nach Tagen (Pro)<input type="number" min="1" name="cookie_safebanner_expiry_days" value="'.$v('expiry_days').'"></label><label>Titel (Pro)<input name="cookie_safebanner_title" value="'.$v('title').'"></label><label class="full">Beschreibung (Pro)<textarea name="cookie_safebanner_description" rows="3">'.$v('description').'</textarea></label><label>Akzeptieren (Pro)<input name="cookie_safebanner_accept" value="'.$v('accept').'"></label><label>Ablehnen (Pro)<input name="cookie_safebanner_reject" value="'.$v('reject').'"></label><label>Anpassen (Pro)<input name="cookie_safebanner_customize" value="'.$v('customize').'"></label><label>Speichern (Pro)<input name="cookie_safebanner_save" value="'.$v('save').'"></label></div></div></section>';return $sections;
});
if(function_exists('wbce_add_action'))wbce_add_action('cookie_banner.settings.save',static function($post){$keys=array('position','theme','color','company','lang','google_consent','layout','project_key','logo','button_style','title','description','accept','reject','customize','save','radius','max_width','offset','expiry_days','revoke_position','revoke_title','revoke_background','revoke_text');$data=array();foreach($keys as $key)$data[$key]=trim((string)($post['cookie_safebanner_'.$key]??''));$data['pro_enabled']=empty($post['cookie_safebanner_pro_enabled'])?'0':'1';$data['show_revoke']=empty($post['cookie_safebanner_show_revoke'])?'0':'1';Settings::set('cookie_banner_safebanner',json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));});
